INSERT INTO `email_templates` VALUES (1,'MOU_SLA_REMINDER','แจ้งเตือนผู้พิจารณา MOU ตามรอบ SLA (วันที่ 1, 3, 5)','MOU SLA Reviewer Reminder (Day 1, 3, 5)','[VITES มช.] แจ้งเตือนเอกสารความร่วมมือรอการพิจารณา {mou_number}','[CMU VITES] Reminder: Pending Collaboration Agreement {mou_number}','เรียน {reviewer_name}, เอกสารความร่วมมือกับ {partner_institution} อยู่ในคิวพิจารณาของท่าน กรุณาดำเนินการภายใน {deadline_date}','Dear {reviewer_name}, The collaboration agreement with {partner_institution} is awaiting your review. Please action before {deadline_date}.','[\"{reviewer_name}\",\"{mou_number}\",\"{partner_institution}\",\"{deadline_date}\"]','2026-09-24 21:35:27','2026-09-24 21:35:27'),(2,'THANK_YOU_LETTER','หนังสือขอบคุณผู้มาเยือนอัตโนมัติ (ภายใน 24 ชม.)','Automated Visitor Thank You Letter (Within 24h)','[CMU] Thank you for visiting Chiang Mai University','[CMU] Thank you for visiting Chiang Mai University','Dear {visitor_name}, On behalf of Chiang Mai University, we would like to convey our sincere appreciation for your visit on {visit_date}.','Dear {visitor_name}, On behalf of Chiang Mai University, we would like to convey our sincere appreciation for your visit on {visit_date}.','[\"{visitor_name}\",\"{institution_name}\",\"{visit_date}\"]','2026-09-24 21:35:27','2026-09-24 21:35:27');
