DROP TABLE IF EXISTS `exchange_programs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `exchange_programs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `program_code` varchar(255) NOT NULL,
  `title_th` varchar(255) NOT NULL,
  `title_en` varchar(255) NOT NULL,
  `cover_image` varchar(255) DEFAULT NULL,
  `country` varchar(255) DEFAULT NULL,
  `degree_level` varchar(255) NOT NULL DEFAULT 'bachelor',
  `short_description` varchar(500) DEFAULT NULL,
  `program_type` enum('inbound_degree','inbound_non_degree','outbound') NOT NULL DEFAULT 'inbound_non_degree',
  `curriculum_type` enum('curricular','extra_curricular') NOT NULL DEFAULT 'curricular',
  `funding_type` varchar(255) NOT NULL DEFAULT 'tuition_waived',
  `activity_type` varchar(255) DEFAULT NULL,
  `organization_id` bigint(20) unsigned NOT NULL,
  `mou_id` bigint(20) unsigned DEFAULT NULL,
  `coordinator_id` bigint(20) unsigned NOT NULL,
  `start_date` date NOT NULL,
  `end_date` date NOT NULL,
  `application_deadline` date NOT NULL,
  `quota` int(11) NOT NULL DEFAULT 10,
  `available_courses` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`available_courses`)),
  `description` text DEFAULT NULL,
  `status` enum('draft','open','reviewing','closed','completed') NOT NULL DEFAULT 'open',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `exchange_programs_program_code_unique` (`program_code`),
  KEY `exchange_programs_organization_id_foreign` (`organization_id`),
  KEY `exchange_programs_coordinator_id_foreign` (`coordinator_id`),
  KEY `exchange_programs_mou_id_foreign` (`mou_id`),
  CONSTRAINT `exchange_programs_coordinator_id_foreign` FOREIGN KEY (`coordinator_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `exchange_programs_mou_id_foreign` FOREIGN KEY (`mou_id`) REFERENCES `mous` (`id`) ON DELETE SET NULL,
  CONSTRAINT `exchange_programs_organization_id_foreign` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
