  `cooperation_counterparts` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`cooperation_counterparts`)),
  `quarterly_tracking_active` tinyint(1) NOT NULL DEFAULT 1,
  `next_quarterly_follow_up_date` date DEFAULT NULL,
