INSERT INTO `feedback_tickets` VALUES (1,'TKT-2026-001',5,'feature_request','general_service',5,NULL,NULL,'ขอเพิ่มปุ่ม Export รายงานกิจกรรม MOU เป็นรูปแบบ PDF เพิ่มเติมจาก Excel','อยากให้ระบบสามารถ Export รายงานกิจกรรมความร่วมมือรายไตรมาสเป็นเอกสาร PDF สำหรับเสนอที่ประชุมคณะกรรมการประจำคณะได้โดยตรงครับ','investigating','ทางทีมพัฒนารับเรื่องแล้วครับ อยู่ระหว่างจัดทำรายงานสรุปในโมดูล Export ครับ',NULL,NULL,'2026-09-24 21:35:27','2026-09-24 21:35:27'),(2,'VOS-2026-0002',5,'vos_service','module_1_mou',5,'CMU-MOU-2026-001','speed_timeliness','ประเมินความพึงพอใจการจัดทำ MOU ข้ามประเทศ','[คะแนนความพึงพอใจ: 5/5 ดาว] ระบบ AI ช่วยกรอกข้อมูลได้รวดเร็วมาก เจ้าหน้าที่ให้คำแนะนำชัดเจน','pending',NULL,NULL,NULL,'2026-09-24 21:35:40','2026-09-24 21:35:40'),(3,'VOS-2026-0003',5,'vos_service','module_2_visa',4,'VS-202609-001','document_accuracy','การแจ้งเตือนวันหมดอายุและต่อวีซ่า','[คะแนนความพึงพอใจ: 4/5 ดาว] การนับถอยหลัง 60 วัน และแจ้งเตือนหน้าวีซ่าสะดวกมากครับ','pending',NULL,NULL,NULL,'2026-09-24 21:35:40','2026-09-24 21:35:40'),(5,'VOS-2026-0004',5,'vos_service','module_1_mou',5,'CMU-MOU-2026-001','speed_timeliness','ประเมินความพึงพอใจการจัดทำ MOU ข้ามประเทศ','[คะแนนความพึงพอใจ: 5/5 ดาว] ระบบ AI ช่วยกรอกข้อมูลได้รวดเร็วมาก เจ้าหน้าที่ให้คำแนะนำชัดเจน','pending',NULL,NULL,NULL,'2026-09-24 21:52:03','2026-09-24 21:52:03'),(6,'VOS-2026-0006',5,'vos_service','module_2_visa',4,'VS-202609-001','document_accuracy','การแจ้งเตือนวันหมดอายุและต่อวีซ่า','[คะแนนความพึงพอใจ: 4/5 ดาว] การนับถอยหลัง 60 วัน และแจ้งเตือนหน้าวีซ่าสะดวกมากครับ','pending',NULL,NULL,NULL,'2026-09-24 21:52:03','2026-09-24 21:52:03'),(8,'VOS-2026-0007',5,'vos_service','module_1_mou',5,'CMU-MOU-2026-001','speed_timeliness','ประเมินความพึงพอใจการจัดทำ MOU ข้ามประเทศ','[คะแนนความพึงพอใจ: 5/5 ดาว] ระบบ AI ช่วยกรอกข้อมูลได้รวดเร็วมาก เจ้าหน้าที่ให้คำแนะนำชัดเจน','pending',NULL,NULL,NULL,'2026-09-24 21:53:43','2026-09-24 21:53:43'),(9,'VOS-2026-0009',5,'vos_service','module_2_visa',4,'VS-202609-001','document_accuracy','การ