DROP TABLE IF EXISTS `inbound_applications`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `inbound_applications` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `exchange_program_id` bigint(20) unsigned NOT NULL,
  `host_faculty_id` bigint(20) unsigned DEFAULT NULL,
  `user_id` bigint(20) unsigned DEFAULT NULL,
  `full_name` varchar(255) NOT NULL,
  `email` varchar(255) NOT NULL,
  `passport_no` varchar(255) NOT NULL,
  `nationality` varchar(255) NOT NULL,
  `home_university` varchar(255) NOT NULL,
  `home_country` varchar(255) NOT NULL,
  `degree_type` enum('degree','non_degree') NOT NULL DEFAULT 'non_degree',
  `activity_type` varchar(255) DEFAULT NULL,
  `start_date` date DEFAULT NULL,
  `end_date` date DEFAULT NULL,
  `period_months` varchar(255) DEFAULT NULL,
  `selected_courses` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`selected_courses`)),
  `transcript_path` varchar(255) DEFAULT NULL,
  `passport_copy_path` varchar(255) DEFAULT NULL,
  `status` enum('submitted','faculty_review','faculty_accepted','faculty_rejected','passed_to_visa','enrolled','completed') NOT NULL DEFAULT 'submitted',
  `faculty_review_notes` text DEFAULT NULL,
  `rejection_reason` text DEFAULT NULL,
  `rejected_by_id` bigint(20) unsigned DEFAULT NULL,
  `rejected_at` timestamp NULL DEFAULT NULL,
  `visa_application_id` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `inbound_applications_exchange_program_id_foreign` (`exchange_program_id`),
  KEY `inbound_applications_user_id_foreign` (`user_id`),
  KEY `inbound_applications_visa_application_id_foreign` (`visa_application_id`),
  KEY `inbound_applications_host_faculty_id_foreign` (`host_faculty_id`),
  KEY `inbound_applications_rejected_by_id_foreign` (`rejected_by_id`),
  CONSTRAINT `inbound_applications_exchange_program_id_foreign` FOREIGN KEY (`exchange_program_id`) REFERENCES `exchange_programs` (`id`) ON DELETE CASCADE,
  CONSTRAINT `inbound_applications_host_faculty_id_foreign` FOREIGN KEY (`host_faculty_id`) REFERENCES `organizations` (`id`) ON DELETE SET NULL,
  CONSTRAINT `inbound_applications_rejected_by_id_foreign` FOREIGN KEY (`rejected_by_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `inbound_applications_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `inbound_applications_visa_application_id_foreign` FOREIGN KEY (`visa_application_id`) REFERENCES `visa_applications` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
