  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ira_chat_logs_user_id_foreign` (`user_id`),
  KEY `ira_chat_logs_session_id_index` (`session_id`),
  CONSTRAINT `ira_chat_logs_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
