INSERT INTO `ira_chat_logs` VALUES (1,'ira_il1oykf2d_1790327797891',1,'partnership_mou','MOU ไหนกำลังจะหมดอายุใน 90 วัน?',NULL,NULL,'### ⏳ รายงานสรุป MOU ที่กำลังจะหมดอายุภายใน 90 วัน (Real-time Database Query)\n\nน้องไอร่าดึงข้อมูลล่าสุดจากฐานข้อมูลระบบ V.I.T.E.S มาให้แล้วค่ะ:\n\n- **Seoul National University** (South Korea)\n  - รหัสสัญญา: `CMU-MOU-2025-002` | ประเภท: MOA_GENERAL\n  - วันหมดอายุ: **09/12/2026** (เหลืออีก ~74.612800455544 วัน)\n  - เจ้าของเรื่อง: คณะวิทยาศาสตร์\n- **Kyoto University** (Japan)\n  - รหัสสัญญา: `CMU-MOU-2025-001` | ประเภท: CoRA\n  - วันหมดอายุ: **15/10/2026** (เหลืออีก ~19.612800455544 วัน)\n  - เจ้าของเรื่อง: คณะวิศวกรรมศาสตร์\n\n\n#### 💡 ข้อเสนอแนะเชิงรุกจาก AI:\n1. สำหรับข้อตกลงที่มีกิจกรรมความร่วมมือต่อเนื่อง แนะนำให้คณะเจ้าของเรื่องเริ่มต้นขั้นตอน **\"ขอต่ออายุสัญญา (Renewal)\"** ก่อนวันหมดอายุอย่างน้อย **60 วัน**\n2. เจ้าหน้าที่ ศพก. สามารถคลิกดราฟต์อีเมลแจ้งเตือนไปยังคณะเจ้าของเรื่องได้ทันทีด้านล่างนี้ค่ะ','draft_email','{\"to\":\"dean.faculty@cmu.ac.th\",\"subject\":\"[\\u0e41\\u0e08\\u0e49\\u0e07\\u0e40\\u0e15\\u0e37\\u0e2d\\u0e19\\u0e40\\u0e1e\\u0e37\\u0e48\\u0e2d\\u0e1e\\u0e34\\u0e08\\u0e32\\u0e23\\u0e13\\u0e32\\u0e15\\u0e48\\u0e2d\\u0e2d\\u0e32\\u0e22\\u0e38] \\u0e02\\u0e49\\u0e2d\\u0e15\\u0e01\\u0e25\\u0e07\\u0e04\\u0e27\\u0e32\\u0e21\\u0e23\\u0e48\\u0e27\\u0e21\\u0e21\\u0e37\\u0e2d\\u0e17\\u0e32\\u0e07\\u0e27\\u0e34\\u0e0a\\u0e32\\u0e01\\u0e32\\u0e23 (MOU) \\u0e43\\u0e01\\u0e25\\u0e49\\u0e04\\u0e23\\u0e1a\\u0e01\\u0e33\\u0e2b\\u0e19\\u0e14\\u0e2d\\u0e32\\u0e22\\u0e38\\u0e2a\\u0e31\\u0e0d\\u0e0d\\u0e32\",\"body\":\"\\u0e40\\u0e23\\u0e35\\u0e22\\u0e19 \\u0e04\\u0e13\\u0e1a\\u0e14\\u0e35 \\/ \\u0e1c\\u0e39\\u0e49\\u0e1b\\u0e23\\u0e30\\u0e2a\\u0e32\\u0e19\\u0e07\\u0e32\\u0e19\\u0e02\\u0e49\\u0e2d\\u0e15\\u0e01\\u0e25\\u0e07\\u0e04\\u0e27\\u0e32\\u0e21\\u0e23\\u0e48\\u0e27\\u0e21\\u0e21\\u0e37\\u0e2d\\n\\n\\u0e28\\u0e39\\u0e19\\u0e22\\u0e4c\\u0e1a\\u0e23\\u0e34\\u0e2b\\u0e32\\u0e23\\u0e1e\\u0e31\\u0e19\\u0e18\\u0e01\\u0e34\\u