04\\u0e25\\u0e34\\u0e2a\\u0e15\\u0e4c\\u0e40\\u0e2d\\u0e01\\u0e2a\\u0e32\\u0e23\\u0e17\\u0e35\\u0e48\\u0e15\\u0e49\\u0e2d\\u0e07\\u0e43\\u0e0a\\u0e49\\u0e2a\\u0e21\\u0e31\\u0e04\\u0e23\",\"query\":\"\\u0e02\\u0e2d\\u0e40\\u0e0a\\u0e47\\u0e04\\u0e25\\u0e34\\u0e2a\\u0e15\\u0e4c\\u0e40\\u0e2d\\u0e01\\u0e2a\\u0e32\\u0e23\\u0e2a\\u0e21\\u0e31\\u0e04\\u0e23\\u0e42\\u0e04\\u0e23\\u0e07\\u0e01\\u0e32\\u0e23\\u0e41\\u0e25\\u0e01\\u0e40\\u0e1b\\u0e25\\u0e35\\u0e48\\u0e22\\u0e19 Outbound\"},{\"label\":\"\\ud83d\\udcc5 \\u0e40\\u0e0a\\u0e47\\u0e04\\u0e01\\u0e33\\u0e2b\\u0e19\\u0e14\\u0e01\\u0e32\\u0e23\\u0e1b\\u0e34\\u0e14\\u0e23\\u0e31\\u0e1a\\u0e2a\\u0e21\\u0e31\\u0e04\\u0e23\\u0e17\\u0e35\\u0e48\\u0e43\\u0e01\\u0e25\\u0e49\\u0e17\\u0e35\\u0e48\\u0e2a\\u0e38\\u0e14\",\"query\":\"\\u0e42\\u0e04\\u0e23\\u0e07\\u0e01\\u0e32\\u0e23\\u0e41\\u0e25\\u0e01\\u0e40\\u0e1b\\u0e25\\u0e35\\u0e48\\u0e22\\u0e19\\u0e17\\u0e35\\u0e48\\u0e01\\u0e33\\u0e25\\u0e31\\u0e07\\u0e40\\u0e1b\\u0e34\\u0e14\\u0e23\\u0e31\\u0e1a\\u0e2a\\u0e21\\u0e31\\u0e04\\u0e23\\u0e41\\u0e25\\u0e30\\u0e40\\u0e14\\u0e14\\u0e44\\u0e25\\u0e19\\u0e4c\"}]',NULL,NULL,'2026-09-25 02:27:13','2026-09-25 02:27:13'),(4,'ira_il1oykf2d_1790327797891',1,'mobility','ขั้นตอนการรายงานตัว 90 วัน สำหรับนักศึกษาต่างชาติ',NULL,NULL,'### 🌐 ผลการวิเคราะห์และข้อแนะนำจาก Mobility Agent\n\nน้องไอร่าได้ตรวจสอบเงื่อนไขโครงการแลกเปลี่ยนและพันธมิตรสากลของ มช. ให้เรียบร้อยแล้วค่ะ:\n\n1. **การตรวจสอบคุณสมบัติเบื้องต้น (General Eligibility):**\n   - เป็นนักศึกษา มช. ชั้นปีที่ 2 ขึ้นไป (ระดับปริญญาตรี) หรือศึกษามาแล้วไม่น้อยกว่า 1 ภาคการศึกษา (ระดับบัณฑิตศึกษา)\n   - ผลการเรียนสะสม (GPAX): ไม่ต่ำกว่า **2.75 - 3.00** ขึ้นอยู่กับเกณฑ์ของมหาวิทยาลัยปลายทาง\n   - ผลทดสอบภาษาอังกฤษ: **IELTS 6.0+** หรือ **TOEFL iBT 78+** (หรือ JLPT N2 สำหรับมหาวิทยาลัยในญี่ปุ่น)\n\n2. **เกณฑ์การสนับสนุนทุนแลกเปลี่ยน:**\n   - มหาวิทยาลัยคู่สัญญา MOU มักจะได้รับ **การยกเว้นค่าธรรมเนียมการศึกษา ณ มหาวิทยาลัยปลายทาง (Tuition-Waiver)**\n   - ทุนสนับสนุนค่าครองชีพรายเดือนจาก CMU Global Mobility Fund หรือทุน JASSO (ญี่ปุ่น) / Erasmus+ (ยุโรป)\n\n\n### 🎓 โครงการแลกเปลี่ยนที่กำลังเปิดรับสมัครในระบบ:\n- **โครงการฝึกอบรมทางคลินิกระยะสั้นสำหรับนักศึกษาแพทย์ต่างชาติ (Non-Degree)** (Clinical Observership Program for International Medical Students)\n  - 🏛️ สถาบัน/คณะ: คณะแพทยศาสตร์ | โควตา: 15 ที่นั่ง\n  - ⏰ กำหนดปิดรับสมัคร: **09/10/2026**\n- **โครงการแลกเปลี่ยนนักศึกษาวิศวกรรมศาสตร์ ณ มหาวิทยาลัยเกียวโต ประเทศญี่ปุ่น** (Engineering Exchange Program at Kyoto University, Japan)\n  - 🏛️ สถาบัน/คณะ: คณะวิศวกรรมศาสตร์ | โควตา: 5 ที่นั่ง\n  - ⏰ กำหนดปิดรับสมัคร: **25/10/2026**\n- **โครงการวิจัยและแลกเปลี่ยนพลังงานสะอาด ณ มหาวิทยาลัยแห่งชาติสิงคโปร์ (NUS)** (Clean Energy & Advanced Tech Fellowship at National University of Singapore)\n  - 🏛️ สถาบัน/คณะ: คณะวิศวกรรมศาสตร์ | โควตา: 4 ที่นั่ง\n  - ⏰ กำหนดปิดรับสมัคร: **20/10/2026**\n- **โครงการศึกษาวัฒนธรรมล้านนาและสิ่งแวดล้อมยั่งยืนสำหรับนักศึกษาต่างชาติ (CMU Summer School)** (Lanna Cultural Heritage & Sustainable Tropical Ecology Summer Program)\n  - 🏛️ สถาบัน/คณะ: คณะวิศวกรรมศาสตร์ | โควตา: 25 ที่นั่ง\n  - ⏰ กำหนดปิดรับสมัคร: **15/10/2026**\n\n3. **กำหนดการสำคัญ:**\n   - ภาคการศึกษา Fall (สิงหาคม/กันยายน): เปิดรับสมัครช่วง **มกราคม - มีนาคม**\n   - ภาคการศึกษา Spring (มกราคม/กุมภาพันธ์): เปิดรับสมัครช่วง **สิงหาคม - ตุลาคม**','download_checklist','{\"title\":\"Checklist \\u0e40\\u0e2d\\u0e01\\u0e2a\\u0e32\\u0e23\\u0e2a\\u0e21\\u0e31\\u0e04\\u0e23\\u0e42\\u0e04\\u0e23\\u0e07\\u0e01\\u0e32\\u0e23\\u0e41\\u0e25\\u0e01\\u0e40\\u0e1b\\u0e25\\u0e35\\u0e48\\u0e22\\u0e19 Outbound\",\"items\":[\"1. \\u0e43\\u0e1a\\u0e41\\u0e2a\\u0e14\\u0e07\\u0e1c\\u0e25\\u0e01\\u0e32\\u0e23\\u0e40\\u0e23\\u0e35\\u0e22\\u0e19 (Academic Transcript \\u0e09\\u0e1a\\u0e31\\u0e1a\\u0e20\\u0e32\\u0e29\\u0e32\\u0e2d\\u0e31\\u0e07\\u0e01\\u0e24\\u0e29)\",\"2. \\u0e1c\\u0e25\\u0e04\\u0e30\\u0e41\\u0e19\\u0e19\\u0e2a\\u0e2d\\u0e1a\\u0e27\\u0e31\\u0e14\\u0e23\\u0e30\\u0e14\\u0e31\\u0e1a\\u0e20\\u0e32\\u0e29\\u0e32 (IELTS \\/ TOEFL \\/ JLPT)\",\"3. \\u0e41\\u0e1c\\u0e19\\u0e01\\u0e32\\u0e23\\u0e28\\u0e36\\u0e01\\u0e29\\u0e32\\u0e41\\u0e25\\u0e30\\u0e01\\u0e32\\u0e23\\u0e40\\u0e17\\u0e35\\u0e22\\u0e1a\\u0e42\\u0e2d\\u0e19\\u0e23\\u0e32\\u0e22\\u0e27\\u0e34\\u0e0a\\u0e32 (Study Plan & Learning Agreement)\",\"4. \\u0e2b\\u0e19\\u0e31\\u0e07\\u0e2a\\u0e37\\u0e2d\\u0e23\\u0e31\\u0e1a\\u0e23\\u0e2d\\u0e07\\u0e08\\u0e32\\u0e01\\u0e2d\\u0e32\\u0e08\\u0e32\\u0e23\\u0e22\\u0e4c\\u0e17\\u0e35\\u0e48\\u0e1b\\u0e23\\u0e36\\u0e01\\u0e29\\u0e32 (Recommendation Letter 2 \\u0e09\\u0e1a\\u0e31\\u0e1a)\",\"5. \\u0e2a\\u0e33\\u0e40\\u0e19\\u0e32\\u0e2b\\u0e19\\u0e31\\u0e07\\u0e2a\\u0e37\\u0e2d\\u0e40\\u0e14\\u0e34\\u0e19\\u0e17\\u0e32\\u0e07 (Passport \\u0e17\\u0e35\\u0e48\\u0e21\\u0e35\\u0e2d\\u0e32\\u0e22\\u0e38\\u0e40\\u0e2b\\u0e25\\u0e37\\u0e2d\\u0e44\\u0e21\\u0e48\\u0e19\\u0e49\\u0e2d\\u0e22\\u0e01\\u0e27\\u0e48\\u0e32 6 \\u0e40\\u0e14\\u0e37\\u0e2d\\u0e19)\",\"6. \\u0e2b\\u0e19\\u0e31\\u0e07\\u0e2a\\u0e37\\u0e2d\\u0e23\\u0e31\\u0e1a\\u0e23\\u0e2d\\u0e07\\u0e2a\\u0e16\\u0e32\\u0e19\\u0e30\\u0e17\\u0e32\\u0e07\\u0e01\\u0e32\\u0e23\\u0e40\\u0e07\\u0e34\\u0e19 (Bank Guarantee \\/ Statement)\"]}',NULL,NULL,'2026-09-25 02:27:33','2026-09-25 02:27:33'),(5,'ira_il1oykf2d_1790327797891',1,'student_journey','มหาวิทยาลัยจองคอร์ทแบทที่ไหน',NULL,NULL,'### 🎒 คำแนะนำการใช้ชีวิตและการศึกษาใน มช. (Student Journey Assistant)\n\nน้องไอร่าพร้อมดูแลนักศึกษาต่างชาติตลอด 4 ช่วงการเดินทางในรั้วมหาวิทยาลัยเชียงใหม่ค่ะ:\n\n#### 1. ก่อนเดินทางมาถึง (Before Arrival)\n- **หนังสือรับรองการตอบรับ (Acceptance Letter):** ใช้ยื่นขอ Non-Immigrant ED Visa ณ สถานเอกอัครราชทูตไทย\n- **การจองที่พัก:** หอพักในกำกับมหาวิทยาลัย (เช่น หอพัก 40 ปี, หอพักสุเทพ) หรือหอพักเอกชนรอบรั้วแคมปัส (ย่านนิมมานฯ / หลังมอ)\n- **CMU Buddy Matching:** เข้าร่วมโปรแกรมเพื่อนคู่คิดชาวไทยเพื่อคอยต้อนรับตั้งแต่วันแรก\n\n#### 2. เมื่อเดินทางมาถึง (Arrival & Onboarding)\n- **การเดินทางจากสนามบินเชียงใหม่ (CNX):** นั่งรถ RTC Bus สาย R3, แท็กซี่สนามบิน หรือบริการรับ-ส่งของคณะ\n- **การเปิดบัญชีธนาคาร:** ธนาคารกรุงเทพ หรือ SCB สาขามหาวิทยาลัยเชียงใหม่ พร้อมหนังสือรับรองจากคณะ\n- **การทำบัตรนักศึกษา (Student ID Card):** ติดต่อสำนักทะเบียนและประมวลผล (อาคาร RB5)\n\n#### 3. ระหว่างศึกษาในแคมปัส (Campus Life & Support)\n- **ประกันสุขภาพ:** นักศึกษาต่างชาติจะได้รับความคุ้มครอง ณ โรงพยาบาลมหาราชนครเชียงใหม่ (สวนดอก) และศูนย์สุขภาพนักศึกษา\n- **การเดินทางใน มช.:** รถไฟฟ้ามหาวิทยาลัย (รถม่วง Smart Shuttle Bus) วิ่งฟรี 5 สายทั่ว มช.\n- **การรายงานตัว 90 วัน:** ติดต่อหน่วยวีซ่า ศพก. ก่อนครบกำหนด\n\n#### 4. เมื่อสำเร็จการศึกษา (Graduation)\n- ยื่นแบบฟอร์มขอจบการศึกษา ชำระหนี้สินและคืนหนังสือห้องสมุด\n- **การยกเลิกวีซ่า (Visa Cancellation):** ยื่นหนังสือขอสละสิทธิ์วีซ่านักศึกษา ณ ตม. เชียงใหม่ ภายใน 21 วันหลังการศึกษาเสร็จสิ้น','schedule_appointment','{\"department\":\"\\u0e2b\\u0e19\\u0e48\\u0e27\\u0e22\\u0e14\\u0e39\\u0e41\\u0e25\\u0e41\\u0e25\\u0e30\\u0e1a\\u0e23\\u0e34\\u0e01\\u0e32\\u0e23\\u0e19\\u0e31\\u0e01\\u0e28\\u0e36\\u0e01\\u0e29\\u0e32\\u0e15\\u0e48\\u0e32\\u0e07\\u0e0a\\u0e32\\u0e15\\u0e34 (International Student Service - \\u0e28\\u0e1e\\u0e01.)\",\"contact_email\":\"iro@cmu.ac.th\",\"location\":\"\\u0e2d\\u0e32\\u0e04\\u0e32\\u0e23\\u0e28\\u0e39\\u0e19\\u0e22\\u0e4c\\u0e1a\\u0e23\\u0e34\\u0e2b\\u0e32\\u0e23\\u0e1e\\u0e31\\u0e19\\u0e18\\u0e01\\u0e34\\u0e08\\u0e2a\\u0e32\\u0e01\\u0e25 \\u0e21\\u0e0a.\",\"hotline\":\"053-943661\"}',NULL,NULL,'2026-09-25 02:27:59','2026-09-25 02:27:59'),(6,'ira_il1oykf2d_1790327797891',1,'student_journey','เส้นทางรถม่วง มช. และการเดินทางในมหาวิทยาลัย',NULL,NULL,'### 🎒 คำแนะนำการใช้ชีวิตและการศึกษาใน มช. (Student Journey Assistant)\n\nน้องไอร่าพร้อมดูแลนักศึกษาต่างชาติตลอด 4 ช่วงการเดินทางในรั้วมหาวิทยาลัยเชียงใหม่ค่ะ:\n\n#### 1. ก่อนเดินทางมาถึง (Before Arrival)\n- **หนังสือรับรองการตอบรับ (Acceptance Letter):** ใช้ยื่นขอ Non-Immigrant ED Visa ณ สถานเอกอัครราชทูตไทย\n- **การจองที่พัก:** หอพักในกำกับมหาวิทยาลัย (เช่น หอพัก 40 ปี, หอพักสุเทพ) หรือหอพักเอกชนรอบรั้วแคมปัส (ย่านนิมมานฯ / หลังมอ)\n- **CMU Buddy Matching:** เข้าร่วมโปรแกรมเพื่อนคู่คิดชาวไทยเพื่อคอยต้อนรับตั้งแต่วันแรก\n\n#### 2. เมื่อเดินทางมาถึง (Arrival & Onboarding)\n- **การเดินทางจากสนามบินเชียงใหม่ (CNX):** นั่งรถ RTC Bus สาย R3, แท็กซี่สนามบิน หรือบริการรับ-ส่งของคณะ\n- **การเปิดบัญชีธนาคาร:** ธนาคารกรุงเทพ หรือ SCB สาขามหาวิทยาลัยเชียงใหม่ พร้อมหนังสือรับรองจากคณะ\n- **การทำบัตรนักศึกษา (Student ID Card):** ติดต่อสำนักทะเบียนและประมวลผล (อาคาร RB5)\n\n#### 3. ระหว่างศึกษาในแคมปัส (Campus Life & Support)\n- **ประกันสุขภาพ:** นักศึกษาต่างชาติจะได้รับความคุ้มครอง ณ โรงพยาบาลมหาราชนครเชียงใหม่ (สวนดอก) และศูนย์สุขภาพนักศึกษา\n- **การเดินทางใน มช.:** รถไฟฟ้ามหาวิทยาลัย (รถม่วง Smart Shuttle Bus) วิ่งฟรี 5 สายทั่ว มช.\n- **การรายงานตัว 90 วัน:** ติดต่อหน่วยวีซ่า ศพก. ก่อนครบกำหนด\n\n#### 4. เมื่อสำเร็จการศึกษา (Graduation)\n- ยื่นแบบฟอร์มขอจบการศึกษา ชำระหนี้สินและคืนหนังสือห้องสมุด\n- **การยกเลิกวีซ่า (Visa Cancellation):** ยื่นหนังสือขอสละสิทธิ์วีซ่านักศึกษา ณ ตม. เชียงใหม่ ภายใน 21 วันหลังการศึกษาเสร็จสิ้น','schedule_appointment','{\"department\":\"\\u0e2b\\u0e19\\u0e48\\u0e27\\u0e22\\u0e14\\u0e39\\u0e41\\u0e25\\u0e41\\u0e25\\u0e30\\u0e1a\\u0e23\\u0e34\\u0e01\\u0e32\\u0e23\\u0e19\\u0e31\\u0e01\\u0e28\\u0e36\\u0e01\\u0e29\\u0e32\\u0e15\\u0e48\\u0e32\\u0e07\\u0e0a\\u0e32\\u0e15\\u0e34 (International Student Service - \\u0e28\\u0e1e\\u0e01.)\",\"contact_email\":\"iro@cmu.ac.th\",\"location\":\"\\u0e2d\\u0e32\\u0e04\\u0e32\\u0e23\\u0e28\\u0e39\\u0e19\\u0e22\\u0e4c\\u0e1a\\u0e23\\u0e34\\u0e2b\\u0e32\\u0e23\\u0e1e\\u0e31\\u0e19\\u0e18\\u0e01\\u0e34\\u0e08\\u0e2a\\u0e32\\u0e01\\u0e25 \\u0e21\\u0e0a.\",\"hotline\":\"053-943661\"}','positive',NULL,'2026-09-25 02:28:20','2026-09-25 02:28:31'),(7,'ira_il1oykf2d_1790327797891',1,'visa','ขั้นตอนการรายงานตัว 90 วัน สำหรับนักศึกษาต่างชาติ',NULL,NULL,'### 🛂 คำแนะนำขั้นตอนจาก Visa & Immigration Agent\n\nน้องไอร่าสรุปขั้นตอนการปฏิบัติสำหรับงานตรวจคนเข้าเมืองและวีซ่าสำหรับนักศึกษา/ผู้เชี่ยวชาญต่างชาติ ดังนี้ค่ะ:\n\n#### 1. การรายงานตัวอยู่ในราชอาณาจักรเกิน 90 วัน (90-Day Notification - TM.47)\n- **ช่วงเวลายื่นเรื่อง:** ยื่นล่วงหน้าได้ **15 วัน** ก่อนครบกำหนด และไม่เกิน **7 วัน** หลังครบกำหนด\n- **ช่องทางบริการ:** \n  1. ระบบออนไลน์ สตม. (Immigration Online e-Service)\n  2. ติดต่อยื่นผ่านหน่วยบริการวีซ่า ศพก. มช. (อาคารศูนย์บริหารพันธกิจสากล ชั้น 1)\n  3. ด่านตรวจคนเข้าเมืองจังหวัดเชียงใหม่ (ตม. พรอมเมนาดา)\n\n#### 2. เอกสารจำเป็นสำหรับการต่ออายุ Non-Immigrant ED Visa (ระยะ 1 ปี)\n- แบบคำขอ ตม.7 พร้อมรูปถ่ายขนาด 4x6 ซม. จำนวน 1 รูป (ถ่ายไม่เกิน 6 เดือน)\n- หนังสือเดินทาง (Passport) ตัวจริง พร้อมสำเนาหน้าข้อมูลและหน้าวีซ่าปัจจุบัน\n- หนังสือรับรองสถานภาพนักศึกษาและขออยู่ต่อ จากสำนักทะเบียน มช. (ออกไม่เกิน 30 วัน)\n- ใบแสดงผลการศึกษา (Official Transcript) ภาคเรียนล่าสุด\n- สำเนาใบรับแจ้งที่พักอาศัย (แบบ ตม.30)\n- ค่าธรรมเนียมคำขอ 1,900 บาท\n\n> ⚠️ **ข้อควรระวังสำคัญ (Legal Disclaimer):**\n> คำแนะนำนี้อ้างอิงตามระเบียบของสำนักงานตรวจคนเข้าเมือง (สตม.) และคู่มือปฏิบัติงานของศูนย์บริหารพันธกิจสากล (ศพก.) มหาวิทยาลัยเชียงใหม่ ข้อมูลนี้มีวัตถุประสงค์เพื่อการอำนวยความสะดวกและแนะนำขั้นตอนเบื้องต้นเท่านั้น มิใช่การวินิจฉัยหรือการตัดสินทางกฎหมาย','schedule_appointment','{\"department\":\"\\u0e2b\\u0e19\\u0e48\\u0e27\\u0e22\\u0e1a\\u0e23\\u0e34\\u0e01\\u0e32\\u0e23\\u0e15\\u0e23\\u0e27\\u0e08\\u0e25\\u0e07\\u0e15\\u0e23\\u0e32\\u0e41\\u0e25\\u0e30\\u0e2b\\u0e19\\u0e31\\u0e07\\u0e2a\\u0e37\\u0e2d\\u0e40\\u0e14\\u0e34\\u0e19\\u0e17\\u0e32\\u0e07 (\\u0e28\\u0e1e\\u0e01. \\u0e0a\\u0e31\\u0e49\\u0e19 1)\",\"contact_email\":\"visa.ira@cmu.ac.th\",\"service_hours\":\"\\u0e08\\u0e31\\u0e19\\u0e17\\u0e23\\u0e4c - \\u0e28\\u0e38\\u0e01\\u0e23\\u0e4c \\u0e40\\u0e27\\u0e25\\u0e32 08:30 - 16:30 \\u0e19. (\\u0e40\\u0e27\\u0e49\\u0e19\\u0e27\\u0e31\\u0e19\\u0e2b\\u0e22\\u0e38\\u0e14\\u0e23\\u0e32\\u0e0a\\u0e01\\u0e32\\u0e23)\",\"location\":\"\\u0e28\\u0e39\\u0e19\\u0e22\\u0e4c\\u0e1a\\u0e23\\u0e34\\u0e2b\\u0e32\\u0e23\\u0e1e\\u0e31\\u0e19\\u0e18\\u0e01\\u0e34\\u0e08\\u0e2a\\u0e32\\u0e01\\u0e25 (IRA Center) \\u0e2d\\u0e32\\u0e04\\u0e32\\u0e23\\u0e27\\u0e34\\u0e40\\u0e17\\u0e28\\u0e2a\\u0e31\\u0e21\\u0e1e\\u0e31\\u0e19\\u0e18\\u0e4c\"}',NULL,NULL,'2026-09-27 20:55:27','2026-09-27 20:55:27'),(8,'ira_il1oykf2d_1790327797891',2,'partnership_mou','ขอนัดหมายล่วงหน้ากับเจ้าหน้าที่งานวีซ่า ศพก.',NULL,NULL,'### 🏛️ ข้อมูลสถานะและบริการด้านความร่วมมือสากล (Partnership & MOU Agent)\n\nน้องไอร่าสรุปภาพรวมข้อตกลงความร่วมมือของมหาวิทยาลัยเชียงใหม่ในปัจจุบัน:\n\n- **ข้อตกลงที่มีผลบังคับใช้ (Active MOUs):** **3** ฉบับ\n- **ข้อตกลงที่อยู่ระหว่างกระบวนการกลั่นกรอง (In Review / Main Board):** **3** ฉบับ\n- **การพิจารณาคู่ขนาน (Concurrent Review):** ดำเนินการพร้อมกัน 4 หน่วยงานหลัก ได้แก่ ศพก. (IRA), นิติการ (LAW), ทรัพย์สินทางปัญญา (TLO), และพัฒนาคุณภาพการศึกษา (Academic Affairs) มีกรอบ SLA รวมไม่เกิน 14 วันทำการ\n\nหากท่านต้องการให้น้องไอร่าช่วยตรวจสอบฉบับใดเป็นพิเศษ หรือต้องการแนบไฟล์ร่างสัญญาเพื่อให้ AI ช่วยสกัดข้อมูล สามารถสอบถามหรืออัปโหลดไฟล์เข้ามาได้ตลอดเวลาค่ะ','view_mou','{\"url\":\"http:\\/\\/localhost\\/vites\\/public\\/mou\\/main-board\",\"label\":\"\\u2696\\ufe0f \\u0e44\\u0e1b\\u0e17\\u0e35\\u0e48\\u0e28\\u0e39\\u0e19\\u0e22\\u0e4c\\u0e1e\\u0e34\\u0e08\\u0e32\\u0e23\\u0e13\\u0e32\\u0e01\\u0e25\\u0e31\\u0e48\\u0e19\\u0e01\\u0e23\\u0e2d\\u0e07 Main Board\"}',NULL,NULL,'2026-09-28 21:41:54','2026-09-28 21:41:54'),(9,'ira_il1oykf2d_1790327797891',2,'partnership_mou','มหาวิทยาลัยไหนควรเป็น Strategic Partner ในปี 2027?',NULL,NULL,'### 🎯 วิเคราะห์เชิงยุทธศาสตร์: มหาวิทยาลัยเป้าหมาย Strategic Partners สำหรับปี 2027\n\nจากการวิเคราะห์ฐานข้อมูลข้อตกลง กิจกรรมการแลกเปลี่ยน และผลงานวิจัยร่วม (Joint Publications) ในระบบ V.I.T.E.S น้องไอร่าขอเสนอแนะพันธมิตรยุทธศาสตร์ ดังนี้ค่ะ:\n\n1. **Kyoto University (ประเทศญี่ปุ่น):**\n   - **จุดแข็ง:** มีความร่วมมือมายาวนาน กิจกรรมวิจัยด้านเกษตรศาสตร์ วิทยาศาสตร์สิ่งแวดล้อม และแพทยศาสตร์มีความถี่สูง\n   - **ข้อเสนอแนะ 2027:** ยกระดับจาก General MOU เป็น **Comprehensive Strategic Partnership Agreement** พร้อมตั้งกองทุนวิจัยร่วม (Joint Seed Fund)\n\n2. **National University of Singapore - NUS (ประเทศสิงคโปร์):**\n   - **จุดแข็ง:** มหาวิทยาลัยอันดับ 1 ของอาเซียน ด้าน AI, Data Science, และ Bio-innovation\n   - **ข้อเสนอแนะ 2027:** ริเริ่มโครงการ Dual Degree Program หรือ Joint Research Lab ร่วมกับคณะวิศวกรรมศาสตร์และวิทยาลัย CAMT\n\n3. **University of Melbourne (ประเทศออสเตรเลีย):**\n   - **จุดแข็ง:** พันธมิตรในภูมิภาคเอเชียแปซิฟิกที่มีการแลกเปลี่ยนนักศึกษาและบุคลากรทางการแพทย์อย่างต่อเนื่อง\n   - **ข้อเสนอแนะ 2027:** ขยายความร่วมมือสู่กลุ่มงาน One Health และการเปลี่ยนแปลงสภาพภูมิอากาศ (Climate Change Resilience)\n\n> 📊 **ดัชนีชี้วัดที่ควรติดตาม:** อัตราการผลิตบัณฑิตร่วม, จำนวนผลงานตีพิมพ์ใน Scopus/WoS Q1, และความคุ้มค่าของงบประมาณสนับสนุน','view_mou','{\"url\":\"http:\\/\\/localhost\\/vites\\/public\\/mou\",\"label\":\"\\ud83d\\udd0d \\u0e15\\u0e23\\u0e27\\u0e08\\u0e2a\\u0e2d\\u0e1a\\u0e2a\\u0e16\\u0e34\\u0e15\\u0e34\\u0e41\\u0e25\\u0e30\\u0e1b\\u0e23\\u0e30\\u0e27\\u0e31\\u0e15\\u0e34 MOU \\u0e01\\u0e31\\u0e1a\\u0e21\\u0e2b\\u0e32\\u0e27\\u0e34\\u0e17\\u0e22\\u0e32\\u0e25\\u0e31\\u0e22\\u0e40\\u0e2b\\u0e25\\u0e48\\u0e32\\u0e19\\u0e35\\u0e49\"}',NULL,NULL,'2026-09-28 21:42:01','2026-09-28 21:42:01'),(10,'ira_il1oykf2d_1790327797891',2,'partnership_mou','สรุปสถานะข้อตกลงที่อยู่ระหว่างพิจารณาใน Main Board',NULL,NULL,'### 🏛️ ข้อมูลสถานะและบริการด้านความร่วมมือสากล (Partnership & MOU Agent)\n\nน้องไอร่าสรุปภาพรวมข้อตกลงความร่วมมือของมหาวิทยาลัยเชียงใหม่ในปัจจุบัน:\n\n- **ข้อตกลงที่มีผลบังคับใช้ (Active MOUs):** **3** ฉบับ\n- **ข้อตกลงที่อยู่ระหว่างกระบวนการกลั่นกรอง (In Review / Main Board):** **3** ฉบับ\n- **การพิจารณาคู่ขนาน (Concurrent Review):** ดำเนินการพร้อมกัน 4 หน่วยงานหลัก ได้แก่ ศพก. (IRA), นิติการ (LAW), ทรัพย์สินทางปัญญา (TLO), และพัฒนาคุณภาพการศึกษา (Academic Affairs) มีกรอบ SLA รวมไม่เกิน 14 วันทำการ\n\nหากท่านต้องการให้น้องไอร่าช่วยตรวจสอบฉบับใดเป็นพิเศษ หรือต้องการแนบไฟล์ร่างสัญญาเพื่อให้ AI ช่วยสกัดข้อมูล สามารถสอบถามหรืออัปโหลดไฟล์เข้ามาได้ตลอดเวลาค่ะ','view_mou','{\"url\":\"http:\\/\\/localhost\\/vites\\/public\\/mou\\/main-board\",\"label\":\"\\u2696\\ufe0f \\u0e44\\u0e1b\\u0e17\\u0e35\\u0e48\\u0e28\\u0e39\\u0e19\\u0e22\\u0e4c\\u0e1e\\u0e34\\u0e08\\u0e32\\u0e23\\u0e13\\u0e32\\u0e01\\u0e25\\u0e31\\u0e48\\u0e19\\u0e01\\u0e23\\u0e2d\\u0e07 Main Board\"}',NULL,NULL,'2026-09-28 21:42:04','2026-09-28 21:42:04'),(11,'ira_il1oykf2d_1790327797891',2,'partnership_mou','MOU ไหนกำลังจะหมดอายุใน 90 วัน?',NULL,NULL,'### ⏳ รายงานสรุป MOU ที่กำลังจะหมดอายุภายใน 90 วัน (Real-time Database Query)\n\nน้องไอร่าดึงข้อมูลล่าสุดจากฐานข้อมูลระบบ V.I.T.E.S มาให้แล้วค่ะ:\n\n- **Seoul National University** (South Korea)\n  - รหัสสัญญา: `CMU-MOU-2025-002` | ประเภท: MOA_GENERAL\n  - วันหมดอายุ: **09/12/2026** (เหลืออีก ~70.80407872684 วัน)\n  - เจ้าของเรื่อง: คณะวิทยาศาสตร์\n- **Kyoto University** (Japan)\n  - รหัสสัญญา: `CMU-MOU-2025-001` | ประเภท: CoRA\n  - วันหมดอายุ: **15/10/2026** (เหลืออีก ~15.80407872684 วัน)\n  - เจ้าของเรื่อง: คณะวิศวกรรมศาสตร์\n\n\n#### 💡 ข้อเสนอแนะเชิงรุกจาก AI:\n1. สำหรับข้อตกลงที่มีกิจกรรมความร่วมมือต่อเนื่อง แนะนำให้คณะเจ้าของเรื่องเริ่มต้นขั้นตอน **\"ขอต่ออายุสัญญา (Renewal)\"** ก่อนวันหมดอายุอย่างน้อย **60 วัน**\n2. เจ้าหน้าที่ ศพก. สามารถคลิกดราฟต์อีเมลแจ้งเตือนไปยังคณะเจ้าของเรื่องได้ทันทีด้านล่างนี้ค่ะ','draft_email','{\"to\":\"dean.faculty@cmu.ac.th\",\"subject\":\"[\\u0e41\\u0e08\\u0e49\\u0e07\\u0e40\\u0e15\\u0e37\\u0e2d\\u0e19\\u0e40\\u0e1e\\u0e37\\u0e48\\u0e2d\\u0e1e\\u0e34\\u0e08\\u0e32\\u0e23\\u0e13\\u0e32\\u0e15\\u0e48\\u0e2d\\u0e2d\\u0e32\\u0e22\\u0e38] \\u0e02\\u0e49\\u0e2d\\u0e15\\u0e01\\u0e25\\u0e07\\u0e04\\u0e27\\u0e32\\u0e21\\u0e23\\u0e48\\u0e27\\u0e21\\u0e21\\u0e37\\u0e2d\\u0e17\\u0e32\\u0e07\\u0e27\\u0e34\\u0e0a\\u0e32\\u0e01\\u0e32\\u0e23 (MOU) \\u0e43\\u0e01\\u0e25\\u0e49\\u0e04\\u0e23\\u0e1a\\u0e01\\u0e33\\u0e2b\\u0e19\\u0e14\\u0e2d\\u0e32\\u0e22\\u0e38\\u0e2a\\u0e31\\u0e0d\\u0e0d\\u0e32\",\"body\":\"\\u0e40\\u0e23\\u0e35\\u0e22\\u0e19 \\u0e04\\u0e13\\u0e1a\\u0e14\\u0e35 \\/ \\u0e1c\\u0e39\\u0e49\\u0e1b\\u0e23\\u0e30\\u0e2a\\u0e32\\u0e19\\u0e07\\u0e32\\u0e19\\u0e02\\u0e49\\u0e2d\\u0e15\\u0e01\\u0e25\\u0e07\\u0e04\\u0e27\\u0e32\\u0e21\\u0e23\\u0e48\\u0e27\\u0e21\\u0e21\\u0e37\\u0e2d\\n\\n\\u0e28\\u0e39\\u0e19\\u0e22\\u0e4c\\u0e1a\\u0e23\\u0e34\\u0e2b\\u0e32\\u0e23\\u0e1e\\u0e31\\u0e19\\u0e18\\u0e01\\u0e34\\u0e08\\u0e2a\\u0e32\\u0e01\\u0e25 (\\u0e28\\u0e1e\\u0e01.) \\u0e02\\u0e2d\\u0e40\\u0e23\\u0e35\\u0e22\\u0e19\\u0e41\\u0e08\\u0e49\\u0e07\\u0e27\\u0e48\\u0e32 \\u0e02\\u0e49\\u0e2d\\u0e15\\u0e01\\u0e25\\u0e07\\u0e04\\u0e27\\u0e32\\u0e21\\u0e23\\u0e48\\u0e27\\u0e21\\u0e21\\u0e37\\u0e2d\\u0e23\\u0e30\\u0e2b\\u0e27\\u0e48\\u0e32\\u0e07\\u0e21\\u0e2b\\u0e32\\u0e27\\u0e34\\u0e17\\u0e22\\u0e32\\u0e25\\u0e31\\u0e22\\u0e40\\u0e0a\\u0e35\\u0e22\\u0e07\\u0e43\\u0e2b\\u0e21\\u0e48 \\u0e41\\u0e25\\u0e30 \\u0e21\\u0e2b\\u0e32\\u0e27\\u0e34\\u0e17\\u0e22\\u0e32\\u0e25\\u0e31\\u0e22\\u0e04\\u0e39\\u0e48\\u0e2a\\u0e31\\u0e0d\\u0e0d\\u0e32 \\u0e01\\u0e33\\u0e25\\u0e31\\u0e07\\u0e08\\u0e30\\u0e04\\u0e23\\u0e1a\\u0e01\\u0e33\\u0e2b\\u0e19\\u0e14\\u0e2d\\u0e32\\u0e22\\u0e38\\u0e2a\\u0e31\\u0e0d\\u0e0d\\u0e32\\u0e20\\u0e32\\u0e22\\u0e43\\u0e19 90 \\u0e27\\u0e31\\u0e19\\u0e02\\u0e49\\u0e32\\u0e07\\u0e2b\\u0e19\\u0e49\\u0e32\\n\\n\\u0e2b\\u0e32\\u0e01\\u0e2a\\u0e48\\u0e27\\u0e19\\u0e07\\u0e32\\u0e19\\u0e02\\u0e2d\\u0e07\\u0e17\\u0e48\\u0e32\\u0e19\\u0e21\\u0e35\\u0e04\\u0e27\\u0e32\\u0e21\\u0e1b\\u0e23\\u0e30\\u0e2a\\u0e07\\u0e04\\u0e4c\\u0e08\\u0e30\\u0e15\\u0e48\\u0e2d\\u0e2d\\u0e32\\u0e22\\u0e38\\u0e04\\u0e27\\u0e32\\u0e21\\u0e23\\u0e48\\u0e27\\u0e21\\u0e21\\u0e37\\u0e2d (Renewal) \\u0e02\\u0e2d\\u0e04\\u0e27\\u0e32\\u0e21\\u0e01\\u0e23\\u0e38\\u0e13\\u0e32\\u0e14\\u0e33\\u0e40\\u0e19\\u0e34\\u0e19\\u0e01\\u0e32\\u0e23\\u0e22\\u0e37\\u0e48\\u0e19\\u0e40\\u0e23\\u0e37\\u0e48\\u0e2d\\u0e07\\u0e1c\\u0e48\\u0e32\\u0e19\\u0e23\\u0e30\\u0e1a\\u0e1a V.I.T.E.S \\u0e40\\u0e1e\\u0e37\\u0e48\\u0e2d\\u0e2a\\u0e48\\u0e07\\u0e43\\u0e2b\\u0e49\\u0e17\\u0e35\\u0e48\\u0e1b\\u0e23\\u0e30\\u0e0a\\u0e38\\u0e21 Main Board \\u0e1e\\u0e34\\u0e08\\u0e32\\u0e23\\u0e13\\u0e32\\u0e15\\u0e48\\u0e2d\\u0e44\\u0e1b\\n\\n\\u0e02\\u0e2d\\u0e41\\u0e2a\\u0e14\\u0e07\\u0e04\\u0e27\\u0e32\\u0e21\\u0e19\\u0e31\\u0e1a\\u0e16\\u0e37\\u0e2d\\n\\u0e28\\u0e39\\u0e19\\u0e22\\u0e4c\\u0e1a\\u0e23\\u0e34\\u0e2b\\u0e32\\u0e23\\u0e1e\\u0e31\\u0e19\\u0e18\\u0e01\\u0e34\\u0e08\\u0e2a\\u0e32\\u0e01\\u0e25 \\u0e21\\u0e2b\\u0e32\\u0e27\\u0e34\\u0e17\\u0e22\\u0e32\\u0e25\\u0e31\\u0e22\\u0e40\\u0e0a\\u0e35\\u0e22\\u0e07\\u0e43\\u0e2b\\u0e21\\u0e48\"}',NULL,NULL,'2026-09-28 21:42:07','2026-09-28 21:42:07'),(12,'ira_il1oykf2d_1790327797891',1,'student_journey','แนะนำโครงการแลกเปลี่ยนนักศึกษา Outbound และเช็คลิสต์เอกสาร',NULL,NULL,'### 🎒 คำแนะนำการใช้ชีวิตและการศึกษาใน มช. (Student Journey Assistant)\n\nน้องไอร่าพร้อมดูแลนักศึกษาต่างชาติตลอด 4 ช่วงการเดินทางในรั้วมหาวิทยาลัยเชียงใหม่ค่ะ:\n\n#### 1. ก่อนเดินทางมาถึง (Before Arrival)\n- **หนังสือรับรองการตอบรับ (Acceptance Letter):** ใช้ยื่นขอ Non-Immigrant ED Visa ณ สถานเอกอัครราชทูตไทย\n- **การจองที่พัก:** หอพักในกำกับมหาวิทยาลัย (เช่น หอพัก 40 ปี, หอพักสุเทพ) หรือหอพักเอกชนรอบรั้วแคมปัส (ย่านนิมมานฯ / หลังมอ)\n- **CMU Buddy Matching:** เข้าร่วมโปรแกรมเพื่อนคู่คิดชาวไทยเพื่อคอยต้อนรับตั้งแต่วันแรก\n\n#### 2. เมื่อเดินทางมาถึง (Arrival & Onboarding)\n- **การเดินทางจากสนามบินเชียงใหม่ (CNX):** นั่งรถ RTC Bus สาย R3, แท็กซี่สนามบิน หรือบริการรับ-ส่งของคณะ\n- **การเปิดบัญชีธนาคาร:** ธนาคารกรุงเทพ หรือ SCB สาขามหาวิทยาลัยเชียงใหม่ พร้อมหนังสือรับรองจากคณะ\n- **การทำบัตรนักศึกษา (Student ID Card):** ติดต่อสำนักทะเบียนและประมวลผล (อาคาร RB5)\n\n#### 3. ระหว่างศึกษาในแคมปัส (Campus Life & Support)\n- **ประกันสุขภาพ:** นักศึกษาต่างชาติจะได้รับความคุ้มครอง ณ โรงพยาบาลมหาราชนครเชียงใหม่ (สวนดอก) และศูนย์สุขภาพนักศึกษา\n- **การเดินทางใน มช.:** รถไฟฟ้ามหาวิทยาลัย (รถม่วง Smart Shuttle Bus) วิ่งฟรี 5 สายทั่ว มช.\n- **การรายงานตัว 90 วัน:** ติดต่อหน่วยวีซ่า ศพก. ก่อนครบกำหนด\n\n#### 4. เมื่อสำเร็จการศึกษา (Graduation)\n- ยื่นแบบฟอร์มขอจบการศึกษา ชำระหนี้สินและคืนหนังสือห้องสมุด\n- **การยกเลิกวีซ่า (Visa Cancellation):** ยื่นหนังสือขอสละสิทธิ์วีซ่านักศึกษา ณ ตม. เชียงใหม่ ภายใน 21 วันหลังการศึกษาเสร็จสิ้น','schedule_appointment','{\"department\":\"\\u0e2b\\u0e19\\u0e48\\u0e27\\u0e22\\u0e14\\u0e39\\u0e41\\u0e25\\u0e41\\u0e25\\u0e30\\u0e1a\\u0e23\\u0e34\\u0e01\\u0e32\\u0e23\\u0e19\\u0e31\\u0e01\\u0e28\\u0e36\\u0e01\\u0e29\\u0e32\\u0e15\\u0e48\\u0e32\\u0e07\\u0e0a\\u0e32\\u0e15\\u0e34 (International Student Service - \\u0e28\\u0e1e\\u0e01.)\",\"contact_email\":\"iro@cmu.ac.th\",\"location\":\"\\u0e2d\\u0e32\\u0e04\\u0e32\\u0e23\\u0e28\\u0e39\\u0e19\\u0e22\\u0e4c\\u0e1a\\u0e23\\u0e34\\u0e2b\\u0e32\\u0e23\\u0e1e\\u0e31\\u0e19\\u0e18\\u0e01\\u0e34\\u0e08\\u0e2a\\u0e32\\u0e01\\u0e25 \\u0e21\\u0e0a.\",\"hotline\":\"053-943661\"}',NULL,NULL,'2026-09-28 23:18:20','2026-09-28 23:18:20');
