INSERT INTO `master_data` VALUES (1,'per_diem_rates','RATE_PRESIDENT','อธิการบดี (President)','President','{\"amount\":3500,\"currency\":\"THB\",\"period\":\"per_day\"}','อัตราเบี้ยเลี้ยงเหมาจ่ายรายวันสำหรับอธิการบดี',1,'2026-09-24 21:35:27','2026-09-24 21:35:27'),(2,'per_diem_rates','RATE_VICE_PRESIDENT','รองอธิการบดี (Vice President)','Vice President','{\"amount\":3100,\"currency\":\"THB\",\"period\":\"per_day\"}','อัตราเบี้ยเลี้ยงเหมาจ่ายรายวันสำหรับรองอธิการบดี',1,'2026-09-24 21:35:27','2026-09-24 21:35:27'),(3,'per_diem_rates','RATE_ASSISTANT_VP','ผู้ช่วยอธิการบดี / คณบดี (Assistant VP / Dean)','Assistant VP / Dean','{\"amount\":2700,\"currency\":\"THB\",\"period\":\"per_day\"}','อัตราเบี้ยเลี้ยงเหมาจ่ายรายวันสำหรับผู้ช่วยอธิการบดีและคณบดี',1,'2026-09-24 21:35:27','2026-09-24 21:35:27'),(4,'per_diem_rates','RATE_OFFICER','เจ้าหน้าที่ผู้ติดตาม / ปฏิบัติงาน','Accompanying Officer','{\"amount\":2100,\"currency\":\"THB\",\"period\":\"per_day\"}','อัตราเบี้ยเลี้ยงเหมาจ่ายรายวันสำหรับเจ้าหน้าที่ร่วมคณะ',1,'2026-09-24 21:35:27','2026-09-24 21:35:27'),(5,'visa_sla_settings','SLA_DOC_VALIDITY','อายุเอกสารอนุญาตขอวีซ่า','Official Doc Validity','{\"days\":60}','เอกสารหนังสือรับรองมีอายุ 60 วันนับจากวันที่ออก',1,'2026-09-24 21:35:27','2026-09-24 21:35:27'),(6,'visa_sla_settings','SLA_PICKUP_DEADLINE','กำหนดรับเอกสารต้นฉบับ','Document Pickup SLA','{\"days\":3}','ต้องมารับเอกสารต้นฉบับภายใน 3 วันทำการ',1,'2026-09-24 21:35:27','2026-09-24 21:35:27'),(7,'visa_sla_settings','SLA_IMMIGRATION_SUBMIT','กำหนดยื่นสำนักงานตรวจคนเข้าเมือง','Immigration Submission SLA','{\"days\":10}','ต้องนำเอกสารไปยื่น ตม. ภายใน 10 วันทำการ',1,'2026-09-24 21:35:27','2026-09-24 21:35:27'),(8,'visa_sla_settings','SLA_STAMP_REPORT','กำหนดรายงานตราประทับวีซ่า','Post-Immigration Stamp Report','{\"days\":15}','ต้องอัปโหลดตราประทับวีซ่ากลับเข้าระบบภายใน 15 วันทำการ',1,'2026-09-24 21:35:27','2026-09-24 21:35:27'),(9,'visitor_sla_settings','SLA_INVITATION_LETTER','ออกหนังสือตอบรับผู้มาเยือน','Invitation Letter SLA','{\"days\":5}','ระบบออกหนังสือตอบรับและประสานงานตารางนัดหมายภายใน 5-7 วันทำการ',1,'2026-09-24 21:35:27','2026-09-24 21:35:27'),(10,'visitor_sla_settings','SLA_THANK_YOU_LETTER','ส่งหนังสือขอบคุณหลังการเยือน','Thank You Letter Delivery','{\"hours\":24}','ส่งหนังสือขอบคุณอัตโนมัติภายใน 24 ชม. หลังเสร็จสิ้นการเยือน',1,'2026-09-24 21:35:27','2026-09-24 21:35:27'),(11,'ai_configuration','AI_COLLABORATION_SCORE_WEIGHTS','เกณฑ์น้ำหนักคะแนน AI Collaboration Score (เต็ม 100 คะแนน)','AI Collaboration Score Weighting Model','{\"global_ranking\":30,\"student_mobility\":20,\"joint_research\":25,\"sdgs_alignment\":15,\"track_record\":10,\"fast_track_threshold\":85,\"committee_threshold\":60,\"total_points\":100}','เกณฑ์น้ำหนักการประเมินคะแนนความร่วมมือโดย AI จาก 5 มิติ รวม 100 คะแนน เพื่อคัดกรอง Fast-track (>=80)',1,'2026-09-24 21:35:27','2026-09-24 21:35:37'),(12,'email_gateway','EMAIL_GATEWAY_CONFIG','การตั้งค่า Email Gateway และเซิร์ฟเวอร์ส่งออก','Outgoing Email Gateway Configuration','{\"smtp_host\":\"smtp.cmu.ac.th\",\"smtp_port\":587,\"encryption\":\"tls\",\"from_email\":\"ira@cmu.ac.th\",\"from_name\":\"\\u0e28\\u0e39\\u0e19\\u0e22\\u0e4c\\u0e1a\\u0e23\\u0e34\\u0e2b\\u0e32\\u0e23\\u0e1e\\u0e31\\u0e19\\u0e18\\u0e01\\u0e34\\u0e08\\u0e2a\\u0e32\\u0e01\\u0e25 \\u0e21\\u0e0a. (IRA Center)\",\"reply_to\":\"ira@cmu.ac.th\",\"daily_limit\":5000}','การเชื่อมต่อระบบอีเมลขาออก (Outgoing SMTP) สำหรับส่งหนังสือแจ้งเตือนและระบบงานสารบรรณ',1,'2026-09-24 21:35:27','2026-09-24 21:35:27'),(13,'mou_approver_groups','group_standard','กลุ่มที่ 1: ศูนย์บริหารพันธกิจสากล (ศพก.) + TLO + นิติการ + อธิการบดี (Standard Main Board)','Standard Main Board Approvers','{\"key\":\"group_standard\",\"sla_days\":14,\"description\":\"\\u0e04\\u0e23\\u0e2d\\u0e1a\\u0e04\\u0e25\\u0e38\\u0e21\\u0e01\\u0e23\\u0e30\\u0e1a\\u0e27\\u0e19\\u0e01\\u0e32\\u0e23\\u0e01\\u0e25\\u0e31\\u0e48\\u0e19\\u0e01\\u0e23\\u0e2d\\u0e07\\u0e21\\u0e32\\u0e15\\u0e23\\u0e10\\u0e32\\u0e19\\u0e15\\u0e32\\u0e21\\u0e01\\u0e23\\u0e2d\\u0e1a\\u0e40\\u0e27\\u0e25\\u0e32 14 \\u0e27\\u0e31\\u0e19\",\"signatories\":[\"\\u0e28\\u0e1e\\u0e01. (IRA Center)\",\"\\u0e2a\\u0e33\\u0e19\\u0e31\\u0e01\\u0e07\\u0e32\\u0e19\\u0e1a\\u0e23\\u0e34\\u0e2b\\u0e32\\u0e23\\u0e07\\u0e32\\u0e19\\u0e27\\u0e34\\u0e08\\u0e31\\u0e22 (TLO)\",\"\\u0e01\\u0e2d\\u0e07\\u0e01\\u0e0e\\u0e2b\\u0e21\\u0e32\\u0e22 (Legal Division)\",\"\\u0e2d\\u0e18\\u0e34\\u0e01\\u0e32\\u0e23\\u0e1a\\u0e14\\u0e35 (President)\"]}','ครอบคลุมกระบวนการกลั่นกรองมาตรฐานตามกรอบเวลา 14 วัน (แจ้งเตือนวันที่ 1, 3, 5)',1,'2026-09-24 21:35:27','2026-09-24 21:35:37'),(14,'mou_approver_groups','group_research','กลุ่มที่ 2: งานวิจัย นวัตกรรม และทรัพย์สินทางปัญญา (ศพก. + TLO + นิติการ + อธิการบดี)','Research, Innovation & IP Approvers','{\"key\":\"group_research\",\"sla_days\":14,\"description\":\"\\u0e40\\u0e19\\u0e49\\u0e19\\u0e01\\u0e32\\u0e23\\u0e04\\u0e38\\u0e49\\u0e21\\u0e04\\u0e23\\u0e2d\\u0e07\\u0e2a\\u0e34\\u0e17\\u0e18\\u0e34\\u0e1a\\u0e31\\u0e15\\u0e23 \\u0e1c\\u0e25\\u0e1b\\u0e23\\u0e30\\u0e42\\u0e22\\u0e0a\\u0e19\\u0e4c\\u0e17\\u0e31\\u0e1a\\u0e0b\\u0e49\\u0e2d\\u0e19 \\u0e41\\u0e25\\u0e30\\u0e01\\u0e32\\u0e23\\u0e08\\u0e31\\u0e14\\u0e2a\\u0e23\\u0e23\\u0e2a\\u0e34\\u0e17\\u0e18\\u0e34\\u0e1b\\u0e23\\u0e30\\u0e42\\u0e22\\u0e0a\\u0e19\\u0e4c\\u0e1c\\u0e25\\u0e07\\u0e32\\u0e19\\u0e27\\u0e34\\u0e08\\u0e31\\u0e22\",\"signatories\":[\"\\u0e28\\u0e1e\\u0e01. (IRA Center)\",\"\\u0e2a\\u0e33\\u0e19\\u0e31\\u0e01\\u0e07\\u0e32\\u0e19\\u0e1a\\u0e23\\u0e34\\u0e2b\\u0e32\\u0e23\\u0e07\\u0e32\\u0e19\\u0e27\\u0e34\\u0e08\\u0e31\\u0e22 (TLO)\",\"\\u0e01\\u0e2d\\u0e07\\u0e01\\u0e0e\\u0e2b\\u0e21\\u0e32\\u0e22 (Legal Division)\",\"\\u0e23\\u0e2d\\u0e07\\u0e2d\\u0e18\\u0e34\\u0e01\\u0e32\\u0e23\\u0e1a\\u0e14\\u0e35\\u0e1d\\u0e48\\u0e32\\u0e22\\u0e27\\u0e34\\u0e08\\u0e31\\u0e22 (VP Research)\",\"\\u0e2d\\u0e18\\u0e34\\u0e01\\u0e32\\u0e23\\u0e1a\\u0e14\\u0e35 (President)\"]}','เน้นการคุ้มครองสิทธิบัตร ผลประโยชน์ทับซ้อน และการจัดสรรสิทธิประโยชน์ผลงานวิจัย',1,'2026-09-24 21:35:27','2026-09-24 21:35:27'),(15,'mou_approver_groups','group_academic','กลุ่มที่ 3: แลกเปลี่ยนนักศึกษาและเทียบโอนหน่วยกิต (ศพก. + สบว. + นิติการ + รองอธิการบดี)','Student Mobility & Credit Transfer Approvers','{\"key\":\"group_academic\",\"sla_days\":14,\"description\":\"\\u0e40\\u0e19\\u0e49\\u0e19\\u0e04\\u0e27\\u0e32\\u0e21\\u0e2a\\u0e2d\\u0e14\\u0e04\\u0e25\\u0e49\\u0e2d\\u0e07\\u0e02\\u0e2d\\u0e07\\u0e2b\\u0e25\\u0e31\\u0e01\\u0e2a\\u0e39\\u0e15\\u0e23 \\u0e42\\u0e04\\u0e23\\u0e07\\u0e2a\\u0e23\\u0e49\\u0e32\\u0e07\\u0e2b\\u0e19\\u0e48\\u0e27\\u0e22\\u0e01\\u0e34\\u0e15 \\u0e41\\u0e25\\u0e30\\u0e04\\u0e27\\u0e32\\u0e21\\u0e1b\\u0e25\\u0e2d\\u0e14\\u0e20\\u0e31\\u0e22\\u0e02\\u0e2d\\u0e07\\u0e19\\u0e31\\u0e01\\u0e28\\u0e36\\u0e01\\u0e29\\u0e32\\u0e41\\u0e25\\u0e01\\u0e40\\u0e1b\\u0e25\\u0e35\\u0e48\\u0e22\\u0e19\",\"signatories\":[\"\\u0e28\\u0e1e\\u0e01. (IRA Center)\",\"\\u0e2a\\u0e33\\u0e19\\u0e31\\u0e01\\u0e1a\\u0e23\\u0e34\\u0e2b\\u0e32\\u0e23\\u0e41\\u0e25\\u0e30\\u0e1e\\u0e31\\u0e12\\u0e19\\u0e32\\u0e27\\u0e34\\u0e0a\\u0e32\\u0e01\\u0e32\\u0e23 (Reg \\/ Academic)\",\"\\u0e01\\u0e2d\\u0e07\\u0e01\\u0e0e\\u0e2b\\u0e21\\u0e32\\u0e22 (Legal Division)\",\"\\u0e23\\u0e2d\\u0e07\\u0e2d\\u0e18\\u0e34\\u0e01\\u0e32\\u0e23\\u0e1a\\u0e14\\u0e35\\u0e1d\\u0e48\\u0e32\\u0e22\\u0e27\\u0e34\\u0e0a\\u0e32\\u0e01\\u0e32\\u0e23 (VP Academic)\"]}','เน้นความสอดคล้องของหลักสูตร โครงสร้างหน่วยกิต และความปลอดภัยของนักศึกษาแลกเปลี่ยน',1,'2026-09-24 21:35:27','2026-09-24 21:35:27'),(16,'mou_approver_groups','group_custom','กลุ่มที่ 4: กำหนดรายบุคคลเฉพาะกรณี (Custom Approver List)','Custom Ad-hoc Approvers List','{\"key\":\"group_custom\",\"sla_days\":14,\"description\":\"\\u0e40\\u0e25\\u0e37\\u0e2d\\u0e01\\u0e1c\\u0e39\\u0e49\\u0e21\\u0e35\\u0e2d\\u0e33\\u0e19\\u0e32\\u0e08\\u0e1e\\u0e34\\u0e08\\u0e32\\u0e23\\u0e13\\u0e32\\u0e40\\u0e09\\u0e1e\\u0e32\\u0e30\\u0e01\\u0e34\\u0e08\\u0e15\\u0e32\\u0e21\\u0e02\\u0e49\\u0e2d\\u0e15\\u0e01\\u0e25\\u0e07\\u0e1e\\u0e34\\u0e40\\u0e28\