DROP TABLE IF EXISTS `mobility_reports`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `mobility_reports` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `outbound_application_id` bigint(20) unsigned NOT NULL,
  `user_id` bigint(20) unsigned NOT NULL,
  `report_title` varchar(255) NOT NULL,
  `executive_summary` text DEFAULT NULL,
  `academic_professional_dev` text DEFAULT NULL,
  `cultural_insights` text DEFAULT NULL,
  `logistics_safety` text DEFAULT NULL,
  `summary_experience` text NOT NULL,
  `academic_achievement` text NOT NULL,
  `photos` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`photos`)),
  `destination_transcript_path` varchar(255) DEFAULT NULL,
  `photos_caption` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`photos_caption`)),
  `evaluation_file_path` varchar(255) DEFAULT NULL,
  `submitted_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
