INSERT INTO `mou_templates` VALUES (1,'Template ภาษาอังกฤษ รูปแบบที่ 1: ระดับมหาวิทยาลัย (University Level)','en','university','draft Academic Collaboration Agreement_Aston U_CMU.pdf',NULL,'แม่แบบข้อตกลงความร่วมมือทางวิชาการและการวิจัยระดับสถาบัน/มหาวิทยาลัย (University-wide Academic Collaboration Agreement)','<h3>MEMORANDUM OF UNDERSTANDING</h3><p>BETWEEN CHIANG MAI UNIVERSITY AND [PARTNER UNIVERSITY]</p><p>Article 1: Scope of Academic Collaboration...</p>',1,1,'2026-09-25 01:39:24','2026-09-25 01:39:24'),(2,'Template ภาษาอังกฤษ รูปแบบที่ 2: ระดับคณะ (Faculty Level)','en','faculty','MOU  and  Addendum 1 Faculty Level.pdf',NULL,'แม่แบบข้อตกลงความร่วมมือระดับคณะ พร้อมภาคผนวกเฉพาะด้าน (Faculty-level MOU & Addendum 1)','<h3>MEMORANDUM OF UNDERSTANDING & ADDENDUM 1</h3><p>BETWEEN FACULTY OF [FACULTY_NAME], CHIANG MAI UNIVERSITY AND [PARTNER FACULTY/UNIVERSITY]</p>',1,1,'2026-09-25 01:39:24','2026-09-25 01:39:24'),(3,'Template ภาษาไทย บันทึกข้อตกลงความร่วมมือ','th','university','MOU ทธ_มช.pdf',NULL,'แม่แบบบันทึกข้อตกลงความร่วมมือฉบับภาษาไทย สำหรับหน่วยงาน องค์กร และสถาบันภายในประเทศ','<h3>บันทึกข้อตกลงความร่วมมือ (MOU)</h3><p>ระหว่าง มหาวิทยาลัยเชียงใหม่ และ [ชื่อหน่วยงานคู่สัญญา]</p>',1,1,'2026-09-25 01:39:24','2026-09-25 01:39:24');
