INSERT INTO `mous` VALUES (1,'CMU-MOU-2025-001','บันทึกข้อตกลงความร่วมมือทางวิชาการและการแลกเปลี่ยนนักศึกษากับมหาวิทยาลัยเกียวโต','Academic & Student Exchange Agreement with Kyoto University','Kyoto University',NULL,'Japan',NULL,'Research University','Academic Collaboration',NULL,'Level 3 - Strategic Partner','student_exchange','CoRA',3,5,NULL,NULL,'2024-09-25','2026-10-15',NULL,'2024-10-09',NULL,NULL,'MEMORANDUM OF UNDERSTANDING BETWEEN CHIANG MAI UNIVERSITY AND KYOTO UNIVERSITY. Clause 1: Student Exchange. Clause 2: Intellectual Property.','completed','student_exchange',92,'low','low','Comprehensive bilateral student exchange and dual-degree framework. Feasibility score 92/100.',NULL,1,NULL,'AI categorized as MOU but this agreement has explicit Joint IP and Co-Research terms. (เดิม AI จำแนกเป็น CoRA)','e_sign',NULL,0,NULL,'direct_president',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2024-09-24 21:35:27',NULL,'active',NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,NULL,'2026-09-24 21:35:27','2026-09-25 02:38:22',NULL,NULL),(2,'CMU-MOU-2025-002','ข้อตกลงการแลกเปลี่ยนทางวิชาการและวิจัยร่วมกับ Seoul National University','Academic & Joint Research Cooperation with Seoul National University','Seoul National University',NULL,'South Korea',NULL,'Research University','Academic Collaboration',NULL,'Level 3 - Strategic Partner','academic','MOA_GENERAL',5,4,NULL,NULL,'2024-09-25','2026-12-09',NULL,'2024-10-09',NULL,NULL,NULL,'completed','academic',85,'low','low','MoA on joint STEM materials research.',NULL,0,NULL,NULL,NULL,NULL,0,NULL,'direct_president',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'in_approval',NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,NULL,'2026-09-24 21:35:27','2026-09-25 02:38:22',NULL,NULL),(3,'CMU-MOU-2025-003','หนังสือแสดงเจตจำนงการพัฒนาหลักสูตรร่วมกับ University of Queensland','Letter of Intent on Curriculum Development with UQ','University of Queensland',NULL,'Australia',NULL,'Research University','Academic Collaboration',NULL,'Level 3 - Strategic Partner','academic','LETTER_OF_INTENT',3,5,NULL,NULL,'2025-03-25','2027-02-22',NULL,NULL,NULL,NULL,NULL,'completed','curriculum',80,'low','low',NULL,NULL,0,NULL,NULL,NULL,NULL,0,NULL,'direct_president',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'active',NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,NULL,'2026-09-24 21:35:27','2026-09-25 02:38:22',NULL,NULL),(4,'CMU-MOU-2026-004','ความร่วมมือด้านการวิจัยพลังงานสะอาดและเทคโนโลยีแบตเตอรี่กับ Technical University of Munich','Research Collaboration on Clean Energy & Battery Technology with TUM','Technical University of Munich (TUM)',NULL,'Germany',NULL,'Research University','Academic Collaboration',NULL,'Level 3 - Strategic Partner','research','JOINT_RESEARCH',5,4,NULL,NULL,'2026-09-25','2029-09-25',NULL,'2026-10-09',NULL,NULL,NULL,'completed','research',88,'low','medium','Research partnership on green energy materials. AI highlighted IP clause 4.2 regarding patent ownership distribution. Score: 88/100.',NULL,1,90,'Admin evaluated mutual grant support from DAAD, boosting feasibility score to 90.',NULL,NULL,0,NULL,'direct_president',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'in_approval',NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,'2026-09-24 21:35:27','2026-09-25 02:38:22',NULL,NULL),(5,'CMU-MOU-2026-005','บันทึกข้อตกลงความร่วมมือด้านการฝึกอบรมแพทย์ประจำบ้านและการวิจัยทางคลินิกกับ Harvard Medical School','Clinical Observership & Residency Training Agreement with Harvard Medical School','Harvard Medical School',NULL,'United States',NULL,'Research University','Academic Collaboration',NULL,'Level 3 - Strategic Partner','academic','CLINICAL_OBSERVER',4,4,NULL,NULL,'2026-07-25','2029-09-25','2029-03-25',NULL,NULL,NULL,NULL,'completed','clinical',95,'low','low','High impact medical partnership. Verified scanned original agreement in repository.',NULL,0,NULL,NULL,'physical_scan',NULL,0,NULL,'delegated',NULL,NULL,'CMU-ORD-2025/114',NULL,NULL,NULL,'group_standard',NULL,'mous/onsite_scans/sample_harvard_mou.pdf','2026-07-24 21:35:27','2026-07-24 21:35:27',NULL,'active',NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,NULL,'2026-09-24 21:35:27','2026-09-25 02:38:22',4,'2026-07-26 21:35:27'),(6,'CMU-MOU-2026-006','ข้อตกลงการจัดตั้งห้องปฏิบัติการร่วมด้านปัญญาประดิษฐ์กับ National University of Singapore','Joint Artificial Intelligence Laboratory Agreement with National University of Singapore (NUS)','National University of Singapore (NUS)',NULL,'Singapore',NULL,'Research University','Academic Collaboration',NULL,'Level 3 - Strategic Partner','research','JOINT_LAB',3,5,NULL,NULL,'2026-09-25','2031-09-25','2031-03-25',NULL,NULL,NULL,NULL,'completed','research',94,'low','low','Joint AI Lab establishment. Agreement signed onsite, pending Central IRD verification.',NULL,0,NULL,NULL,'physical_scan',NULL,0,NULL,'direct_president',NULL,NULL,NULL,NULL,NULL,NULL,'group_research',NULL,'mous/onsite_scans/sample_nus_lab_agreement.pdf','2026-09-24 17:35:27','2026-09-25 01:00:04',NULL,'in_approval',NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,'2026-09-24 21:35:27','2026-09-25 02:38:22',NULL,NULL);
