INSERT INTO `news_articles` VALUES (1,'Driving Chiang Mai University\'s Internationalization Strategy Towards Vision 2030','cmu-internationalization-strategy-vision-2030','strategy','ศูนย์บริหารพันธกิจสากล (IRA Center) มหาวิทยาลัยเชียงใหม่ เดินหน้าขับเคลื่อนยุทธศาสตร์ความเป็นสากล มุ่งสู่วิสัยทัศน์ \'A Leading University Committed to Social Responsibility and Sustainable Development\' บูรณาการแพลตฟอร์ม V.I.T.E.S และความร่วมมือ 15 รูปแบบสู่ระดับโลก','ศูนย์บริหารพันธกิจสากล (International Relations Administration Center - IRA Center) สำนักงานมหาวิทยาลัย มหาวิทยาลัยเชียงใหม่ มุ่งมั่นขับเคลื่อนยุทธศาสตร์ความเป็นสากลของมหาวิทยาลัยตามวิสัยทัศน์ \'A Leading University Committed to Social Responsibility and Sustainable Development\' โดยพัฒนาระบบนิเวศดิจิทัล V.I.T.E.S เพื่อรวมศูนย์การบริหารจัดการเอกสารความร่วมมือทางวิชาการ (MOU/MOA 15 รูปแบบ), การให้บริการวีซ่าออนไลน์แบบมี SLA และการติดตามความคืบหน้าของโครงการแลกเปลี่ยนนักศึกษาและคณาจารย์ทั่วโลกอย่างโปร่งใส รวดเร็ว และตรวจสอบได้แบบเรียลไทม์','https://images.unsplash.com/photo-1541339907198-e08756dedf3f?auto=format&fit=crop&w=1200&q=80',4,'ศูนย์บริหารพันธกิจสากล (IRA Center)',142,890,'[\"IRA Center\",\"Vision 2030\",\"SDGs\",\"Global Strategy\"]',1,'2026-09-22 21:35:27','2026-09-24 21:35:27','2026-09-24 21:35:27'),(2,'เปิดรับสมัครทุนแลกเปลี่ยนนักศึกษา Kyoto University Summer Exchange 2026 (Full Scholarship)','kyoto-university-summer-exchange-scholarship-2026','scholarship','โอกาสพิเศษสำหรับนักศึกษาระดับปริญญาตรีและบัณฑิตศึกษา มช. เข้าร่วมศึกษาและวิจัยระยะสั้น ณ Kyoto University ประเทศญี่ปุ่น พร้อมสนับสนุนค่าเดินทางและค่าครองชีพเต็มจำนวนภายใต้กรอบ CMU-MOU','IRA Center ประกาศเปิดรับสมัครคัดเลือกนักศึกษามหาวิทยาลัยเชียงใหม่ เพื่อเข้าร่วมโครงการศึกษาแลกเปลี่ยนระยะสั้น Kyoto University Summer Program 2026 ณ เมืองเกียวโต ประเทศญี่ปุ่น ภายใต้ข้อตกลงความร่วมมือทางวิชาการระดับมหาวิทยาลัย (CMU-MOU Framework) โดยผู้ผ่านการคัดเลือกจะได้รับทุนสนับสนุนค่าตั๋วเครื่องบินและค่าครองชีพตลอดระยะเวลาโครงการ สามารถสมัครผ่านระบบ V.I.T.E.S ได้ตั้งแต่บัดนี้จนถึงวันที่ 30 พฤศจิกายน 2526','https://images.unsplash.com/photo-1493976040374-85c8e12f0c0e?auto=format&fit=crop&w=1200&q=80',4,'งานพัฒนาความร่วมมือระหว่างประเทศ ศพก.',98,650,'[\"Scholarship\",\"Japan\",\"Kyoto Univ\",\"Outbound Mobility\"]',1,'2026-09-19 21:35:27','2026-09-24 21:35:27','2026-09-24 21:35:27'),(3,'มช. ลงนามบันทึกข้อตกลงวิจัยร่วมขั้นสูง (CoRA) ด้านพลังงานสะอาดกับ National University of Singapore','cmu-nus-cora-clean-energy-partnership','mou','ยกระดับความร่วมมือสู่การวิจัยเชิงลึกด้าน Clean Energy และ Carbon Neutrality พร้อมเปิดศูนย์วิจัยร่วม Joint Lab และแลกเปลี่ยนนักวิจัยแนวหน้าระหว่างสองมหาวิทยาลัยชั้นนำ','มหาวิทยาลัยเชียงใหม่ โดยศูนย์บริหารพันธกิจสากลและคณะวิศวกรรมศาสตร์ ได้จัดพิธีลงนามข้อตกลงความร่วมมือการวิจัยเฉพาะทาง (Collaborative Research Agreement - CoRA) ร่วมกับ National University of Singapore (NUS) เพื่อมุ่งเน้นการพัฒนานวัตกรรมเซลล์แสงอาทิตย์รุ่นใหม่และระบบกักเก็บพลังงานสะอาด สอดคล้องกับยุทธศาสตร์มหาวิทยาลัยสู่ความเป็นกลางทางคาร์บอน (Carbon Neutrality) ภายในปี 2032 โดยกระบวนการลงนามดำเนินการผ่านระบบ CMU e-Sign พร้อมบันทึกหลักฐานการลงนามแบบดิจิทัลครบวงจร','https://images.unsplash.com/photo-1523240795612-9a054b0db644?auto=format&fit=crop&w=1200&q=80',4,'งานส่งเสริมความร่วมมือทางวิชาการ ศพก.',76,520,'[\"CoRA\",\"NUS\",\"Clean Energy\",\"CMU e-Sign\"]',1,'2026-09-16 21:35:27','2026-09-24 21:35:27','2026-09-24 21:35:27'),(4,'เปิดใช้งานระบบติดตามวีซ่าออนไลน์ CMU Visa Online SLA (60/30/15 วัน) พร้อมแจ้งเตือนผ่าน LINE OA','cmu-visa-online-sla-line-oa-launch','visa','บริการใหม่จาก IRA Center ยกระดับการบริการอาจารย์ นักวิจัย และนักศึกษาต่างชาติ (Inbound Scholars) ด้วยระบบแจ้งเตือนต่ออายุวีซ่าอัตโนมัติ แม่นยำ รวดเร็ว ไม่พลาดกำหนดการ สตม.','เพื่ออำนวยความสะดวกแก่อาจารย์ นักวิจัย และนักศึกษาชาวต่างชาติที่พำนักในมหาวิทยาลัยเชียงใหม่ ศูนย์บริหารพันธกิจสากลได้เปิดตัวโมดูล Visa Online SLA Tracking บนแพลตฟอร์ม V.I.T.E.S ซึ่งเชื่อมโยงข้อมูลโดยตรงกับระบบสำนักทะเบียนและ สตม. จังหวัดเชียงใหม่ พร้อมฟังก์ชันแจ้งเตือนล่วงหน้าแบบเรียลไทม์ 60 วัน, 30 วัน, และ 15 วัน ผ่าน LINE Official Account เพื่อลดข้อผิดพลาดการอยู่เกินกำหนด (Overstay) เป็นศูนย์ (0%)','https://images.unsplash.com/photo-1577495508048-b635879837f1?auto=format&fit=crop&w=1200&q=80',4,'งานบริการชาวต่างประเทศ (Visa & Services) ศพก.',115,780,'[\"Visa SLA\",\"LINE OA\",\"Inbound\",\"Immigration\"]',1,'2026-09-12 21:35:27','2026-09-24 21:35:27','2026-09-24 21:35:27');
/*!40000 ALTER TABLE `news_articles` ENABLE KEYS */;
